// Day 7: Requires Expressions and Requirement Kinds
#include <concepts>
#include <iostream>

struct Number {
    using value_type = int;
    int value{};
};

Number operator+(Number a, Number b) {
    return {a.value + b.value};
}

template<class T>
concept SmallAddable = requires(T a, T b) {
    typename T::value_type;              // Type requirement
    a + b;                               // Simple requirement
    { a + b } -> std::same_as<T>;        // Compound requirement
    requires (sizeof(T) <= 8);           // Nested requirement
};

int main() {
    std::cout << std::boolalpha << SmallAddable<Number> << '\n';
}

// Day 8: Defining Custom Concepts
#include <concepts>
#include <iostream>

template<class T>
concept Addable = requires(T a, T b) {
    { a + b } -> std::same_as<T>;
};

template<Addable T>
T twice(T value) {
    return value + value;
}

int main() {
    std::cout << "twice(6) = " << twice(6) << '\n';
}

