class Item {
public:
    explicit Item(int id) : id_(id) { ++live_count_; }
    Item(const Item& other) : id_(other.id_) { ++live_count_; }
    ~Item() { --live_count_; }

    int id() const { return id_; }
    static int live_count() { return live_count_; }

private:
    int id_{};
    inline static int live_count_{};
};

