#include <atomic>
#include <iostream>
#include <mutex>
#include <thread>

struct alignas(64) PaddedCounter {
    PaddedCounter() : value(0) {}
    std::atomic<int> value;
};

int main() {
    PaddedCounter left;
    PaddedCounter right; // padding reduces likely cache-line sharing

    std::thread first([&] {
        for (int i = 0; i < 1000; ++i) {
            left.value.fetch_add(1, std::memory_order_relaxed);
        }
    });
    std::thread second([&] {
        for (int i = 0; i < 1000; ++i) {
            right.value.fetch_add(1, std::memory_order_relaxed);
        }
    });

    std::mutex a;
    std::mutex b;
    std::lock(a, b); // deadlock-aware acquisition
    std::lock_guard<std::mutex> lock_a(a, std::adopt_lock);
    std::lock_guard<std::mutex> lock_b(b, std::adopt_lock);

    first.join();
    second.join();
    std::cout << left.value << ',' << right.value << '\n';
}

#include <array>
#include <atomic>
#include <cstddef>
#include <iostream>
#include <thread>

class SpscQueue {
public:
    SpscQueue() : head_(0), tail_(0) {}

    bool push(int value) {
        const std::size_t tail = tail_.load(std::memory_order_relaxed);
        const std::size_t next = (tail + 1) % data_.size();
        if (next == head_.load(std::memory_order_acquire)) {
            return false;
        }
        data_[tail] = value;
        tail_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(int& value) {
        const std::size_t head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) {
            return false;
        }
        value = data_[head];
        head_.store((head + 1) % data_.size(), std::memory_order_release);
        return true;
    }

private:
    std::array<int, 4> data_;
    std::atomic<std::size_t> head_;
    std::atomic<std::size_t> tail_;
};

int main() {
    SpscQueue queue;
    std::thread producer([&] {
        for (int value = 1; value <= 3; ++value) {
            while (!queue.push(value)) {}
        }
    });
    std::thread consumer([&] {
